{
  "suspects": [
    {
      "sentenceId": "sent-7",
      "reason": "上下文提及《三摩地王經》及阿賴耶識，此處應為該經中著名的「如幻」或「夢境」比喻段落，ASR可能漏掉關鍵喻詞。",
      "suspectedMissingTerm": "如幻/夢",
      "promptHints": ["三摩地王經 如幻", "三摩地王經 夢"]
    },
    {
      "sentenceId": "sent-35",
      "reason": "前文談論創造世界，後文接《山本帝王記》(應為《入中論善顯密意疏》或相關論典誤聽)談微塵。此處「唯識創造」語意不完整，通常對比的是外道神我創造與佛教業感緣起，或指唯識宗的「萬法唯心」。",
      "suspectedMissingTerm": "萬法唯心/業感",
      "promptHints": ["唯識 創造世界", "入中論 微塵 創造"]
    },
    {
      "sentenceId": "sent-43",
      "reason": "「任截金」極可能是ASR誤聽，結合上下文「相續運轉成...微塵建立一切」，應指外道或某些部派主張的「極微」(paramāṇu) 或特定論典中的名詞。",
      "suspectedMissingTerm": "極微/原子",
      "promptHints": ["相續 微塵 建立", "入中論 任截金"]
    },
    {
      "sentenceId": "sent-54",
      "reason": "「普得切祿」明顯為ASR誤聽，結合上下文「上帝創造...佛教會不會講...創造世界」，應指外道神我或大自在天等創造者概念。",
      "suspectedMissingTerm": "大自在天/神我",
      "promptHints": ["佛教 創造世界 外道", "入中論 普得切祿"]
    },
    {
      "sentenceId": "sent-76",
      "reason": "「自份緣起」應為「自性緣起」或特定宗義下的術語，但後文提到「唯名安立」，此處對比的是有自性與無自性的緣起。若指中觀應成派觀點，可能漏掉否定詞或特定修飾。",
      "suspectedMissingTerm": "自性/無自性",
      "promptHints": ["三種緣起 自性", "入中論 緣起 分類"]
    },
    {
      "sentenceId": "sent-91",
      "reason": "「自行空」應為「自性空」。ASR將「性」誤聽為「行」。這是核心名相漏字/錯字。",
      "suspectedMissingTerm": "自性空",
      "promptHints": ["第三種緣起 自性空"]
    },
    {
      "sentenceId": "sent-169",
      "reason": "「相遇」在因明與中觀討論因果時，通常指「同時存在」或「接觸」。此處講者可能在確認因果是否「同時」或「異時」，ASR可能漏掉關鍵限定詞如「同時」。",
      "suspectedMissingTerm": "同時/異時",
      "promptHints": ["因 果 相遇 同時"]
    },
    {
      "sentenceId": "sent-181",
      "reason": "「切啦...叮啦、地嘛」是藏文音譯。結合上下文「執分緣起」(應為自性緣起或分別安立)，此處可能在講藏文中表示「存在」或「有」的詞，如 yod (有) 或 bde (樂?)，但更可能是指「依他起」或特定術語。ASR完全無法辨識藏文音譯對應的漢語名相。",
      "suspectedMissingTerm": "依他起/分別安立",
      "promptHints": ["藏文 緣起 術語", "入中論 執分"]
    },
    {
      "sentenceId": "sent-217",
      "reason": "「對因生派」應為「對自續派」或「對經部/有部」。結合後文「既是由因所生，也是自性有」，這是自續派的觀點。ASR將「自續」誤聽為「因生」。",
      "suspectedMissingTerm": "自續派",
      "promptHints": ["自續派 自性有 唯名安立"]
    },
    {
      "sentenceId": "sent-250",
      "reason": "「波羅心經」應為《般若心經》或《大般若經》。「鞭...多鞭」極可能是ASR誤聽，結合上下文談論虛妄、掉下去，可能是在講「二諦」或「名言/勝義」的區別，或是特定比喻。",
      "suspectedMissingTerm": "般若/二諦",
      "promptHints": ["般若心經 虛妄", "入中論 鞭"]
    },
    {
      "sentenceId": "sent-308",
      "reason": "「為是」應為「唯識」或「唯名」。結合上下文「一體空的這樣一個虛妄」，可能在討論唯識宗的遍計所執性。ASR漏掉關鍵宗派或性質詞。",
      "suspectedMissingTerm": "唯識/遍計所執",
      "promptHints": ["唯識 虛妄 空"]
    },
    {
      "sentenceId": "sent-366",
      "reason": "「依理而有」在應成派中通常指「名言中有」或「依名言而有」。若說世間有是「依理而有」，可能漏掉「名言」二字，因為應成派主張名言中成立。",
      "suspectedMissingTerm": "名言",
      "promptHints": ["世間 依理而有 名言"]
    },
    {
      "sentenceId": "sent-457",
      "reason": "「緣子」與「離緣子」應為「有緣子」(因) 與「無緣子」(果?) 或特定比喻。結合前文「原子跟分子」，此處可能在講因果的連續性。ASR可能將「有/無」或特定術語誤聽。",
      "suspectedMissingTerm": "有/無",
      "promptHints": ["入中論 緣子 離緣子"]
    }
  ]
}
